  const paidOrders = () => eventOrders().filter(o=>o.status==="paid");
  const finance = () => {const orders=paidOrders(), revenue=orders.reduce((n,o)=>n+lineTotal(o),0),cogs=orders.reduce((n,o)=>n+itemCost(o),0),expenses=currentEvent().expense;return {revenue,cogs,expenses,profit:revenue-cogs-expenses,paid:orders.length,waiting:eventTickets().filter(k=>k.status==="waiting").length}};
